-- =====================================================================
-- Mise à jour 21 : les 100 questions du Défi du jour
-- Questions 1 à 50 : islam de base (semaine 1 de chaque manche).
-- Questions 51 à 100 : Ahlul Bayt et fiqh ja'farite (semaine 2).
-- Source : supabase/defi-questions.json. Après une correction, relancer ce script :
-- les textes sont mis à jour, l'historique des réponses est conservé.
-- Pour retirer une question : update public.quiz_questions set active = false where id = … ;
-- À coller dans Supabase : SQL Editor > New query > Run (après la mise à jour 20).
-- =====================================================================

on conflict (id) do update set level = excluded.level, theme = excluded.theme, question = excluded.question,
  choices = excluded.choices, answer = excluded.answer, explanation = excluded.explanation;
