insert into public.quiz_questions (id, level, theme, question, choices, answer, explanation) values
  (1, 1, 'Prière', 'Combien de prières obligatoires un musulman accomplit-il chaque jour ?', array['5', '7', '4', '3'], 0, 'Les cinq prières quotidiennes : l''aube (fajr), le midi (dhuhr), l''après-midi (''asr), le coucher du soleil (maghrib) et la nuit (''isha).'),
  (2, 1, 'Prière', 'Combien d''unités (rak''a) compte la prière de l''aube (fajr) ?', array['2', '1', '4', '3'], 0, 'La prière du fajr compte 2 rak''a.'),
  (3, 1, 'Prière', 'Combien d''unités (rak''a) compte la prière du maghrib ?', array['2', '4', '3', '5'], 2, 'La prière du maghrib est la seule prière quotidienne de 3 rak''a.'),
  (4, 1, 'Prière', 'Au total, combien de rak''a obligatoires compte une journée de prières (hors voyage) ?', array['21', '19', '15', '17'], 3, '2 (fajr) + 4 (dhuhr) + 4 (''asr) + 3 (maghrib) + 4 (''isha) = 17 rak''a.'),
  (5, 1, 'Prière', 'Vers quel lieu les musulmans se tournent-ils pour prier ?', array['Al-Aqsa', 'Le mont Arafat', 'La Ka''ba', 'La mosquée du Prophète'], 2, 'La qibla est la Ka''ba, à La Mecque.'),
  (6, 1, 'Prière', 'Quelle sourate récite-t-on obligatoirement dans chaque prière ?', array['Al-Kawthar', 'Al-Fatiha', 'Al-Ikhlas', 'Yasin'], 1, 'La sourate Al-Fatiha est récitée dans chaque prière.'),
  (7, 1, 'Purification', 'Que doit-on faire avant la prière si l''on n''a pas les ablutions ?', array['Rien', 'Faire les ablutions (wudu)', 'Se parfumer', 'Réciter une sourate'], 1, 'Les ablutions (wudu) sont une condition de validité de la prière.'),
  (8, 1, 'Purification', 'Que fait-on à la place des ablutions quand il n''y a pas d''eau ou qu''on ne peut pas l''utiliser ?', array['Le tayammum', 'On reporte la prière au lendemain', 'Le ghusl', 'Rien'], 0, 'Le tayammum, fait avec de la terre pure, remplace les ablutions quand l''eau manque ou ne peut pas être utilisée.'),
  (9, 1, 'Jeûne', 'Pendant quel mois les musulmans jeûnent-ils obligatoirement ?', array['Rajab', 'Sha''ban', 'Ramadan', 'Muharram'], 2, 'Le jeûne du mois de Ramadan est obligatoire (Coran 2:183-185).'),
  (10, 1, 'Jeûne', 'Ramadan est le combientième mois du calendrier hégirien ?', array['10e', '8e', '7e', '9e'], 3, 'Ramadan est le 9e mois du calendrier lunaire hégirien.'),
  (11, 1, 'Jeûne', 'Selon le Coran, durant quel mois se trouve la Nuit du Destin (Laylat al-Qadr) ?', array['Sha''ban', 'Ramadan', 'Dhul-Hijja', 'Rajab'], 1, 'Le Coran a été descendu durant le mois de Ramadan (2:185) et durant la Nuit du Destin (97:1).'),
  (12, 1, 'Jeûne', 'Quelle fête marque la fin du mois de Ramadan ?', array['Le Ghadir', 'L''Aïd al-Fitr', 'L''Aïd al-Adha', 'Le Mawlid'], 1, 'L''Aïd al-Fitr est célébré le 1er jour du mois de Shawwal.'),
  (13, 1, 'Pèlerinage', 'Dans quelle ville se déroule le pèlerinage (Hajj) ?', array['Médine', 'Kerbala', 'Jérusalem', 'La Mecque'], 3, 'Le Hajj se déroule à La Mecque et dans ses environs (Arafat, Muzdalifa, Mina).'),
  (14, 1, 'Pèlerinage', 'Combien de tours fait-on autour de la Ka''ba lors du tawaf ?', array['10', '7', '5', '3'], 1, 'Le tawaf comporte 7 tours autour de la Ka''ba.'),
  (15, 1, 'Pèlerinage', 'Entre quelles collines fait-on le parcours (sa''y) lors du pèlerinage ?', array['Mina et Muzdalifa', 'Hira et Thawr', 'Uhud et Arafat', 'Safa et Marwa'], 3, 'Le sa''y se fait 7 fois entre Safa et Marwa, en souvenir de Hajar cherchant de l''eau pour Isma''il.'),
  (16, 1, 'Pèlerinage', 'Pendant quel mois a lieu le pèlerinage (Hajj) ?', array['Ramadan', 'Muharram', 'Dhul-Hijja', 'Safar'], 2, 'Le Hajj a lieu au mois de Dhul-Hijja, le 12e mois du calendrier hégirien.'),
  (17, 1, 'Pèlerinage', 'Quel prophète a construit la Ka''ba avec son fils Isma''il ?', array['Nuh', 'Ibrahim', 'Musa', 'Dawud'], 1, 'Le Coran rapporte qu''Ibrahim et Isma''il élevèrent les fondations de la Maison (2:127).'),
  (18, 1, 'Coran', 'Combien de sourates compte le Coran ?', array['110', '120', '114', '99'], 2, 'Le Coran compte 114 sourates.'),
  (19, 1, 'Coran', 'Quelle est la plus longue sourate du Coran ?', array['Yasin', 'An-Nisa', 'Al-Baqara', 'Al-''Imran'], 2, 'Al-Baqara (la Vache), 2e sourate, est la plus longue avec 286 versets.'),
  (20, 1, 'Coran', 'Quelle est la plus courte sourate du Coran ?', array['Al-Kawthar', 'Al-Ikhlas', 'Al-''Asr', 'An-Nas'], 0, 'Al-Kawthar compte 3 versets.'),
  (21, 1, 'Coran', 'Quel fut le premier mot révélé au Prophète Muhammad ﷺ ?', array['Iqra'' (Lis)', 'Qul (Dis)', 'Bismillah', 'Al-hamdu'], 0, 'Les premiers versets révélés commencent par « Iqra'' » (Lis), sourate Al-''Alaq (96:1).'),
  (22, 1, 'Coran', 'Dans quelle grotte le Prophète ﷺ a-t-il reçu la première révélation ?', array['Thawr', 'Hira', 'Uhud', 'Arafat'], 1, 'La première révélation eut lieu dans la grotte de Hira, près de La Mecque.'),
  (23, 1, 'Coran', 'Quel ange a transmis la révélation au Prophète ﷺ ?', array['Mika''il', 'Israfil', '''Izra''il', 'Jibra''il'], 3, 'L''ange Jibra''il (Gabriel) a transmis le Coran au Prophète ﷺ.'),
  (24, 1, 'Coran', 'Quelle sourate ne commence pas par « Bismillah ar-Rahman ar-Rahim » ?', array['Al-Fatiha', 'At-Tawba', 'Yasin', 'Al-Baqara'], 1, 'La sourate At-Tawba (9) est la seule à ne pas commencer par la basmala.'),
  (25, 1, 'Coran', 'Dans quelle sourate se trouve le Verset du Trône (Ayat al-Kursi) ?', array['Al-Mulk', 'Al-Baqara', 'Al-Kahf', 'Ar-Rahman'], 1, 'Ayat al-Kursi est le verset 255 de la sourate Al-Baqara.'),
  (26, 1, 'Coran', 'Combien de versets compte la sourate Al-Fatiha ?', array['8', '5', '6', '7'], 3, 'Al-Fatiha compte 7 versets, d''où son nom « les sept versets répétés ».'),
  (27, 1, 'Coran', 'Quelle sourate porte le nom d''une femme ?', array['Al-Mujadila', 'Fatir', 'Al-Mumtahana', 'Maryam'], 3, 'La sourate Maryam (19) porte le nom de la mère du Prophète ''Isa.'),
  (28, 1, 'Coran', 'Quelle sourate résume le tawhid (l''unicité de Dieu) : « Dis : Il est Allah, Unique » ?', array['An-Nas', 'Al-Falaq', 'Al-Ikhlas', 'Al-Kafirun'], 2, 'La sourate Al-Ikhlas (112) décrit l''unicité absolue de Dieu.'),
  (29, 1, 'Prophètes', 'Quel est le dernier des prophètes ?', array['''Isa', 'Musa', 'Ibrahim', 'Muhammad ﷺ'], 3, 'Muhammad ﷺ est le Sceau des prophètes (Coran 33:40).'),
  (30, 1, 'Prophètes', 'Quel prophète a construit l''arche ?', array['Nuh', 'Hud', 'Salih', 'Lut'], 0, 'Le Prophète Nuh a construit l''arche sur ordre de Dieu.'),
  (31, 1, 'Prophètes', 'Quel prophète a été avalé par un grand poisson ?', array['Yunus', 'Yusuf', 'Ayyub', 'Idris'], 0, 'Le Prophète Yunus a été avalé par un grand poisson, puis sauvé par son invocation.'),
  (32, 1, 'Prophètes', 'Quel prophète a reçu la Torah (Tawrat) ?', array['''Isa', 'Ibrahim', 'Dawud', 'Musa'], 3, 'La Torah a été révélée au Prophète Musa.'),
  (33, 1, 'Prophètes', 'Quel prophète comprenait le langage des fourmis et des oiseaux ?', array['Shu''ayb', 'Zakariyya', 'Yahya', 'Sulayman'], 3, 'Le Coran raconte que Sulayman comprenait le langage des oiseaux et entendit une fourmi (sourate An-Naml).'),
  (34, 1, 'Prophètes', 'Quel prophète a été jeté dans le feu, qui est devenu fraîcheur et paix ?', array['Nuh', 'Ibrahim', 'Musa', 'Isma''il'], 1, '« Ô feu, sois fraîcheur et paix pour Ibrahim » (Coran 21:69).'),
  (35, 1, 'Prophètes', 'Quel prophète a été vendu par ses frères puis est devenu ministre en Égypte ?', array['Yahya', 'Harun', 'Yusuf', 'Ya''qub'], 2, 'L''histoire de Yusuf est racontée dans la sourate qui porte son nom (12).'),
  (36, 1, 'Vie du Prophète', 'Comment s''appelait la mère du Prophète Muhammad ﷺ ?', array['Halima', 'Khadija', 'Amina', 'Fatima'], 2, 'Sa mère était Amina bint Wahb ; son père, ''Abdullah, est décédé avant sa naissance.'),
  (37, 1, 'Vie du Prophète', 'Quel oncle a élevé et protégé le Prophète ﷺ après la mort de son grand-père ?', array['Abu Talib', '''Abbas', 'Hamza', 'Abu Lahab'], 0, 'Abu Talib, père de l''Imam ''Ali, a élevé et protégé le Prophète ﷺ.'),
  (38, 1, 'Vie du Prophète', 'Qui fut la première épouse du Prophète ﷺ ?', array['Umm Salama', 'Sawda', 'Zaynab', 'Khadija'], 3, 'Khadija bint Khuwaylid fut sa première épouse et soutint la mission dès le début.'),
  (39, 1, 'Vie du Prophète', 'À quel âge le Prophète ﷺ a-t-il reçu la première révélation ?', array['40 ans', '33 ans', '53 ans', '25 ans'], 0, 'La mission prophétique a commencé à l''âge de 40 ans.'),
  (40, 1, 'Vie du Prophète', 'Quel était l''ancien nom de la ville de Médine ?', array['Yathrib', 'Badr', 'Khaybar', 'Taïf'], 0, 'Médine s''appelait Yathrib avant l''arrivée du Prophète ﷺ.'),
  (41, 1, 'Vie du Prophète', 'En quelle année de l''ère chrétienne a eu lieu l''Hégire vers Médine ?', array['632', '622', '570', '610'], 1, 'L''Hégire a eu lieu en 622 ; elle marque le début du calendrier musulman.'),
  (42, 1, 'Vie du Prophète', 'Quelle fut la première grande bataille des musulmans, en l''an 2 de l''Hégire ?', array['Uhud', 'Badr', 'Hunayn', 'Khandaq'], 1, 'La bataille de Badr eut lieu en l''an 2 de l''Hégire.'),
  (43, 1, 'Vie du Prophète', 'Qui fut le premier muezzin de l''islam ?', array['Abu Dharr', '''Ammar', 'Salman', 'Bilal'], 3, 'Bilal ibn Rabah fut le premier à faire l''appel à la prière.'),
  (44, 1, 'Vie du Prophète', 'Lors du voyage nocturne (Isra''), de quelle mosquée à quelle mosquée le Prophète ﷺ fut-il transporté ?', array['De La Mecque (al-Haram) à al-Aqsa', 'De Médine à La Mecque', 'De Quba à Médine', 'D''al-Aqsa à Médine'], 0, '« Gloire à Celui qui a fait voyager de nuit Son serviteur de la Mosquée sacrée à la Mosquée al-Aqsa » (17:1).'),
  (45, 1, 'Croyance', 'Quel ange soufflera dans la trompe au Jour du Jugement ?', array['Israfil', 'Jibra''il', 'Malik', 'Mika''il'], 0, 'L''ange Israfil est chargé de souffler dans la trompe.'),
  (46, 1, 'Comportement', 'Selon le Coran, comment doit-on se comporter envers ses parents ?', array['Aucune consigne', 'Seulement les écouter', 'Avec bonté, sans même dire « ouf »', 'Les respecter s''ils sont musulmans'], 2, '« Ne leur dis pas même “ouf”, ne les brusque pas, et adresse-leur des paroles respectueuses » (17:23).'),
  (47, 1, 'Comportement', 'Comment s''appelle le fait de parler en mal d''une personne absente ?', array['L''orgueil', 'La jalousie', 'La médisance (ghiba)', 'Le mensonge'], 2, 'La médisance est comparée dans le Coran au fait de manger la chair de son frère mort (49:12).'),
  (48, 1, 'Comportement', 'Quelle formule dit-on avant de commencer une action ?', array['Subhan Allah', 'Al-hamdu lillah', 'Bismillah', 'Allahu akbar'], 2, 'On commence par « Bismillah » : au nom de Dieu.'),
  (49, 1, 'Calendrier', 'Quel est le premier mois du calendrier hégirien ?', array['Muharram', 'Ramadan', 'Safar', 'Rajab'], 0, 'Muharram est le premier mois de l''année hégirienne.'),
  (50, 1, 'Calendrier', 'Le calendrier musulman est basé sur…', array['Les saisons', 'Les étoiles', 'La lune', 'Le soleil'], 2, 'C''est un calendrier lunaire de 12 mois, environ 11 jours plus court que l''année solaire.'),
  (51, 2, 'Ahlul Bayt', 'Combien y a-t-il d''Imams dans l''école ja''farite ?', array['14', '12', '10', '7'], 1, 'Douze Imams, de l''Imam ''Ali à l''Imam al-Mahdi (que Dieu hâte sa venue).'),
  (52, 2, 'Ahlul Bayt', 'Qui est le premier Imam ?', array['L''Imam Husayn', 'L''Imam ''Ali', 'L''Imam as-Sajjad', 'L''Imam Hasan'], 1, 'L''Imam ''Ali ibn Abi Talib, Amir al-Mu''minin.'),
  (53, 2, 'Ahlul Bayt', 'Où est né l''Imam ''Ali ?', array['À Médine', 'Dans la Ka''ba', 'À Taïf', 'À Kufa'], 1, 'L''Imam ''Ali est né à l''intérieur de la Ka''ba, le 13 Rajab.'),
  (54, 2, 'Ahlul Bayt', 'Quelle est la date de naissance de l''Imam ''Ali ?', array['15 Ramadan', '13 Rajab', '3 Sha''ban', '18 Dhul-Hijja'], 1, 'L''Imam ''Ali est né le 13 Rajab, dans la Ka''ba.'),
  (55, 2, 'Ahlul Bayt', 'Quel est le nom de l''épée célèbre de l''Imam ''Ali ?', array['Al-Ma''thur', 'Dhul-Fiqar', 'Al-Battar', 'Al-Qadib'], 1, '« Il n''y a de jeune homme que ''Ali, et il n''y a d''épée que Dhul-Fiqar. »'),
  (56, 2, 'Ahlul Bayt', 'Lors de quelle bataille l''Imam ''Ali arracha-t-il la porte de la forteresse ?', array['Hunayn', 'Badr', 'Khaybar', 'Uhud'], 2, 'À Khaybar, le Prophète ﷺ confia l''étendard à ''Ali, qui arracha la porte de la forteresse.'),
  (57, 2, 'Ahlul Bayt', 'Lors de quelle bataille l''Imam ''Ali affronta-t-il ''Amr ibn ''Abd Wudd ?', array['Khandaq (la Tranchée)', 'Badr', 'Siffin', 'Jamal'], 0, 'À la bataille de la Tranchée, l''Imam ''Ali releva le défi d''Amr ibn ''Abd Wudd.'),
  (58, 2, 'Ahlul Bayt', 'À quelle date a eu lieu l''événement de Ghadir Khumm ?', array['18 Dhul-Hijja', '10 Muharram', '27 Rajab', '15 Sha''ban'], 0, 'Le 18 Dhul-Hijja de l''an 10, au retour du pèlerinage d''adieu.'),
  (59, 2, 'Ahlul Bayt', 'Quel recueil réunit les sermons, lettres et paroles de l''Imam ''Ali ?', array['Mafatih al-Jinan', 'Nahj al-Balagha', 'Al-Kafi', 'As-Sahifa as-Sajjadiyya'], 1, 'Nahj al-Balagha a été compilé par Sharif ar-Radi.'),
  (60, 2, 'Ahlul Bayt', 'Quelle invocation l''Imam ''Ali a-t-il enseignée à son compagnon Kumayl ?', array['Du''a Nudba', 'Du''a ''Arafa', 'Du''a Iftitah', 'Du''a Kumayl'], 3, 'Du''a Kumayl, souvent récitée la nuit du jeudi au vendredi.'),
  (61, 2, 'Ahlul Bayt', 'Dans quelle ville se trouve le mausolée de l''Imam ''Ali ?', array['Najaf', 'Samarra', 'Kufa', 'Kerbala'], 0, 'L''Imam ''Ali est enterré à Najaf, en Irak.'),
  (62, 2, 'Ahlul Bayt', 'Quel jour du mois de Ramadan l''Imam ''Ali est-il tombé en martyr ?', array['19', '15', '21', '27'], 2, 'Frappé à la mosquée de Kufa le 19 Ramadan, il est tombé en martyr le 21 Ramadan de l''an 40.'),
  (63, 2, 'Ahlul Bayt', 'Qui est la mère de l''Imam Hasan et de l''Imam Husayn ?', array['Fatima az-Zahra', 'Khadija', 'Umm al-Banin', 'Zaynab'], 0, 'Sayyida Fatima az-Zahra, fille du Prophète ﷺ.'),
  (64, 2, 'Ahlul Bayt', 'Où se trouve la tombe de Sayyida Fatima az-Zahra ?', array['À Kerbala', 'À Najaf', 'Son emplacement exact est inconnu', 'À La Mecque'], 2, 'Selon sa volonté, elle fut enterrée de nuit ; l''emplacement exact de sa tombe à Médine reste inconnu.'),
  (65, 2, 'Ahlul Bayt', 'Combien de fois dit-on « Allahu akbar » dans le tasbih de Fatima az-Zahra ?', array['100', '35', '33', '34'], 3, '34 « Allahu akbar », 33 « Al-hamdu lillah » et 33 « Subhan Allah ».'),
  (66, 2, 'Ahlul Bayt', 'Qui sont les cinq personnes réunies sous le manteau (Hadith al-Kisa'') ?', array['Le Prophète, ''Ali, Fatima, Hasan et Husayn', 'Les cinq premiers Imams', 'Le Prophète et quatre compagnons', 'Le Prophète, Khadija, ''Ali, Hasan et Husayn'], 0, 'Les Ahl al-Kisa'' : le Prophète ﷺ, l''Imam ''Ali, Sayyida Fatima, l''Imam Hasan et l''Imam Husayn.'),
  (67, 2, 'Ahlul Bayt', 'Dans quelle sourate se trouve le verset de la purification (Tathir) ?', array['Al-Kahf', 'Al-Baqara', 'Al-Ahzab', 'Maryam'], 2, '« Allah veut seulement éloigner de vous la souillure, ô gens de la Maison… » (33:33).'),
  (68, 2, 'Ahlul Bayt', 'Selon le hadith des deux poids (Thaqalayn), que le Prophète ﷺ a-t-il laissé ?', array['Médine et La Mecque', 'Le Coran et sa famille (Ahlul Bayt)', 'Le Coran et la Ka''ba', 'Le Coran et la Sunna seule'], 1, '« Je laisse parmi vous deux choses précieuses : le Livre d''Allah et ma famille, les gens de ma Maison. »'),
  (69, 2, 'Ahlul Bayt', 'Avec qui le Prophète ﷺ a-t-il fait la Mubahala ?', array['Les chrétiens de Najran', 'Les Perses', 'Les juifs de Khaybar', 'Les Quraysh'], 0, 'Il s''y présenta avec ''Ali, Fatima, Hasan et Husayn (verset 3:61).'),
  (70, 2, 'Ahlul Bayt', 'Quel Imam a conclu un traité de paix avec Mu''awiya ?', array['L''Imam ''Ali', 'L''Imam Husayn', 'L''Imam Hasan', 'L''Imam Baqir'], 2, 'L''Imam Hasan al-Mujtaba a conclu ce traité pour préserver la communauté.'),
  (71, 2, 'Ahlul Bayt', 'Où est enterré l''Imam Hasan al-Mujtaba ?', array['À Kerbala', 'Au cimetière d''al-Baqi'' à Médine', 'À Najaf', 'À Damas'], 1, 'L''Imam Hasan repose au cimetière d''al-Baqi'', à Médine.'),
  (72, 2, 'Ahlul Bayt', 'Quelle est la date de naissance de l''Imam Husayn ?', array['10 Muharram', '3 Sha''ban', '13 Rajab', '20 Safar'], 1, 'L''Imam Husayn est né le 3 Sha''ban de l''an 4 de l''Hégire.'),
  (73, 2, 'Kerbala', 'Quel jour a eu lieu la tragédie de Kerbala ?', array['10 Muharram (Ashura)', '18 Dhul-Hijja', '1er Muharram', '20 Safar'], 0, 'Le jour d''Ashura, le 10 Muharram de l''an 61.'),
  (74, 2, 'Kerbala', 'En quelle année de l''Hégire a eu lieu Kerbala ?', array['80', '61', '40', '50'], 1, 'La tragédie de Kerbala a eu lieu en l''an 61 de l''Hégire.'),
  (75, 2, 'Kerbala', 'Qui était le porte-étendard de l''Imam Husayn à Kerbala ?', array['''Ali al-Akbar', 'Abu al-Fadl al-''Abbas', 'Muslim ibn ''Aqil', 'Al-Hurr'], 1, 'Abu al-Fadl al-''Abbas, demi-frère de l''Imam Husayn, surnommé Qamar Bani Hashim.'),
  (76, 2, 'Kerbala', 'Qui l''Imam Husayn a-t-il envoyé à Kufa avant Kerbala ?', array['Habib ibn Mazahir', 'Muslim ibn ''Aqil', 'Zuhayr ibn al-Qayn', 'Al-''Abbas'], 1, 'Son cousin Muslim ibn ''Aqil, tombé en martyr à Kufa.'),
  (77, 2, 'Kerbala', 'Qui a prononcé le célèbre sermon à la cour de Yazid, à Damas ?', array['Sukayna', 'Rubab', 'Sayyida Zaynab', 'Umm Kulthum'], 2, 'Sayyida Zaynab, sœur de l''Imam Husayn, par son éloquence et son courage.'),
  (78, 2, 'Kerbala', 'Quel Imam était présent à Kerbala mais malade pendant la bataille ?', array['L''Imam as-Sajjad', 'L''Imam Baqir', 'L''Imam Sadiq', 'L''Imam Hasan'], 0, 'L''Imam ''Ali Zayn al-''Abidin as-Sajjad, fils de l''Imam Husayn.'),
  (79, 2, 'Kerbala', 'Combien de jours après Ashura commémore-t-on l''Arba''in ?', array['60', '30', '40', '7'], 2, 'L''Arba''in, le 20 Safar, marque le 40e jour après Ashura.'),
  (80, 2, 'Ahlul Bayt', 'Quel Imam est l''auteur des invocations d''as-Sahifa as-Sajjadiyya ?', array['L''Imam ''Ali', 'L''Imam Rida', 'L''Imam Sadiq', 'L''Imam as-Sajjad'], 3, 'L''Imam Zayn al-''Abidin as-Sajjad, le 4e Imam.'),
  (81, 2, 'Ahlul Bayt', 'Quel Imam est surnommé « Baqir al-''Ulum » (celui qui fend les sciences) ?', array['L''Imam Ja''far as-Sadiq', 'L''Imam Muhammad al-Baqir', 'L''Imam Hasan al-''Askari', 'L''Imam Musa al-Kazim'], 1, 'L''Imam Muhammad al-Baqir, le 5e Imam.'),
  (82, 2, 'Ahlul Bayt', 'L''école « ja''farite » porte le nom de quel Imam ?', array['L''Imam Muhammad al-Jawad', 'L''Imam Hasan', 'L''Imam ''Ali', 'L''Imam Ja''far as-Sadiq'], 3, 'L''Imam Ja''far as-Sadiq, le 6e Imam, a transmis le savoir à des milliers d''élèves.'),
  (83, 2, 'Ahlul Bayt', 'Où sont enterrés les Imams Hasan, as-Sajjad, al-Baqir et as-Sadiq ?', array['Au cimetière d''al-Baqi'' (Médine)', 'À Samarra', 'À Kazimiya', 'À Mashhad'], 0, 'Ces quatre Imams reposent au cimetière d''al-Baqi'', à Médine.'),
  (84, 2, 'Ahlul Bayt', 'Quel Imam est surnommé « Bab al-Hawa''ij » (la porte des besoins) ?', array['L''Imam ''Ali al-Hadi', 'L''Imam Husayn', 'L''Imam ''Ali ar-Rida', 'L''Imam Musa al-Kazim'], 3, 'L''Imam Musa al-Kazim, le 7e Imam, longtemps emprisonné sous Harun ar-Rashid.'),
  (85, 2, 'Ahlul Bayt', 'Dans quelle ville se trouve le mausolée de l''Imam ''Ali ar-Rida ?', array['Samarra', 'Mashhad', 'Bagdad', 'Qom'], 1, 'L''Imam ar-Rida, le 8e Imam, repose à Mashhad, en Iran.'),
  (86, 2, 'Ahlul Bayt', 'Qui est enterrée à Qom ?', array['Sayyida Fatima al-Ma''suma', 'Sayyida Zaynab', 'Umm al-Banin', 'Sayyida Ruqayya'], 0, 'Sayyida Fatima al-Ma''suma, sœur de l''Imam ar-Rida.'),
  (87, 2, 'Ahlul Bayt', 'Quels Imams sont enterrés à Kazimiya (Bagdad) ?', array['Hasan et Husayn', 'Musa al-Kazim et Muhammad al-Jawad', '''Ali al-Hadi et Hasan al-''Askari', 'Al-Baqir et as-Sadiq'], 1, 'Le 7e et le 9e Imam reposent à Kazimiya.'),
  (88, 2, 'Ahlul Bayt', 'Quels Imams sont enterrés à Samarra ?', array['As-Sajjad et al-Baqir', '''Ali al-Hadi et Hasan al-''Askari', 'Musa al-Kazim et Muhammad al-Jawad', '''Ali et Husayn'], 1, 'Le 10e et le 11e Imam reposent à Samarra, en Irak.'),
  (89, 2, 'Ahlul Bayt', 'Quel Imam est devenu Imam alors qu''il était encore enfant, vers l''âge de 8 ans ?', array['L''Imam as-Sajjad', 'L''Imam Musa al-Kazim', 'L''Imam Hasan al-''Askari', 'L''Imam Muhammad al-Jawad'], 3, 'L''Imam Muhammad al-Jawad (at-Taqi), le 9e Imam.'),
  (90, 2, 'Imam al-Mahdi', 'Qui est le père de l''Imam al-Mahdi ?', array['L''Imam Hasan al-''Askari', 'L''Imam Muhammad al-Jawad', 'L''Imam ''Ali al-Hadi', 'L''Imam ar-Rida'], 0, 'L''Imam Hasan al-''Askari, le 11e Imam.'),
  (91, 2, 'Imam al-Mahdi', 'Quelle est la date de naissance de l''Imam al-Mahdi ?', array['13 Rajab', '17 Rabi'' al-Awwal', '1er Muharram', '15 Sha''ban'], 3, 'L''Imam al-Mahdi (que Dieu hâte sa venue) est né le 15 Sha''ban de l''an 255.'),
  (92, 2, 'Imam al-Mahdi', 'Combien de représentants spéciaux l''Imam al-Mahdi a-t-il eus durant l''occultation mineure ?', array['4', '12', '2', '7'], 0, 'Quatre représentants spéciaux (nuwwab) ; avec la mort du dernier commença l''occultation majeure.'),
  (93, 2, 'Imam al-Mahdi', 'Quelle invocation récite-t-on traditionnellement le vendredi matin en attendant l''Imam al-Mahdi ?', array['Du''a Kumayl', 'Du''a Sabah', 'Du''a Nudba', 'Du''a Tawassul'], 2, 'Du''a Nudba exprime le désir de voir l''Imam du Temps.'),
  (94, 2, 'Croyance', 'Combien de principes de la religion (usul ad-din) compte l''école ja''farite ?', array['10', '7', '5', '3'], 2, 'L''unicité (tawhid), la justice divine (''adl), la prophétie (nubuwwa), l''imamat (imama) et la résurrection (ma''ad).'),
  (95, 2, 'Croyance', 'Dans les principes de la religion, que signifie « al-''Adl » ?', array['La générosité', 'La patience', 'La prière', 'La justice divine'], 3, 'Allah est juste et ne commet aucune injustice.'),
  (96, 2, 'Fiqh', 'Peut-on suivre quelqu''un (taqlid) dans les principes de la religion (usul ad-din) ?', array['Non, chacun doit en être convaincu par lui-même', 'Oui, toujours', 'Seulement pour l''imamat', 'Seulement après 40 ans'], 0, 'La conviction dans les usul ad-din doit venir de soi ; le taqlid concerne les règles pratiques (furu'').'),
  (97, 2, 'Fiqh', 'Quelle part du surplus annuel le khums représente-t-il ?', array['1/10', '1/5', '1/40', '1/4'], 1, 'Le khums représente un cinquième (20 %) du surplus annuel.'),
  (98, 2, 'Fiqh', 'Sur quoi se prosterne-t-on dans la prière, selon le fiqh ja''farite ?', array['Sur la terre ou ce qui en pousse, ni mangé ni porté', 'Sur un tapis en laine', 'Sur n''importe quel tissu', 'Sur la nourriture'], 0, 'D''où l''usage de la turba (morceau d''argile), notamment de Kerbala.'),
  (99, 2, 'Fiqh', 'Combien de takbir compte la prière du mort (salat al-mayyit) chez les ja''farites ?', array['7', '5', '6', '4'], 1, '5 takbir, avec entre eux la shahada, la salawat, une invocation pour les croyants puis pour le défunt.'),
  (100, 2, 'Fiqh', 'Dans le wudu ja''farite, dans quel sens lave-t-on les bras ?', array['On ne lave pas les bras', 'Dans n''importe quel sens', 'Du coude vers le bout des doigts', 'Des doigts vers le coude'], 2, 'On lave le bras droit puis le gauche, du coude vers le bout des doigts.')
